const cloneDeep = <T,>(value: T): T => JSON.parse(JSON.stringify(value));

const mergeWithDefaults = <T extends object>(
  defaults: T,
  incoming: unknown
): T => {
  const result = cloneDeep(defaults) as Record<string, unknown>;

  if (!incoming || typeof incoming !== 'object') {
    return result as T;
  }

  const source = incoming as Record<string, unknown>;

  Object.entries(result).forEach(([key, defaultValue]) => {
    const value = source[key];

    if (Array.isArray(defaultValue)) {
      if (Array.isArray(value)) {
        result[key] = cloneDeep(value);
      }
      return;
    }

    if (typeof defaultValue === 'boolean') {
      result[key] = typeof value === 'boolean' ? value : defaultValue;
      return;
    }

    if (typeof defaultValue === 'string') {
      result[key] = typeof value === 'string' ? value : defaultValue;
      return;
    }

    if (defaultValue && typeof defaultValue === 'object') {
      result[key] = mergeWithDefaults(
        defaultValue as Record<string, unknown>,
        value
      );
      return;
    }

    if (value !== undefined) {
      result[key] = cloneDeep(value);
    }
  });

  return result as T;
};

