const generateTempId = () => `tmp-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

const cloneDefaultPriceListUnits = (): SupplierPriceListUnitsSettings => ({
  priceLists: DEFAULT_SUPPLIER_PRICE_LIST_UNITS.priceLists.map((item) => ({ ...item })),
  units: DEFAULT_SUPPLIER_PRICE_LIST_UNITS.units.map((item) => ({ ...item }))
});

const normalizeSupplierPriceListUnits = (
  data?: SupplierPriceListUnitsSettings
): SupplierPriceListUnitsSettings => {
  const defaults = cloneDefaultPriceListUnits();

  const normalizedPriceLists = Array.isArray(data?.priceLists) && data?.priceLists.length
    ? data!.priceLists.map((list) => ({
      id: typeof list.id === 'string' && list.id.length > 0 ? list.id : generateTempId(),
      code: list.code ?? '',
      name: list.name ?? '',
      comment: list.comment ?? '',
      preselected: Boolean(list.preselected)
    }))
    : defaults.priceLists.map((list) => ({ ...list }));

  if (normalizedPriceLists.length > 0 && !normalizedPriceLists.some((list) => list.preselected)) {
    normalizedPriceLists[0] = { ...normalizedPriceLists[0], preselected: true };
  }

  const normalizedUnits = Array.isArray(data?.units) && data?.units.length
    ? data!.units.map((unit) => ({
      id: typeof unit.id === 'string' && unit.id.length > 0 ? unit.id : generateTempId(),
      code: unit.code ?? '',
      codeEng: unit.codeEng ?? '',
      text: unit.text ?? ''
    }))
    : defaults.units.map((unit) => ({ ...unit }));

  return {
    priceLists: normalizedPriceLists,
    units: normalizedUnits
  };
};

