const createEmptyDefaultAccountsSettings = (): DefaultAccountsSettings => ({
  ...DEFAULT_ACCOUNTS_PLACEHOLDER
});

const mapDefaultAccountsFromApi = (apiData: any): DefaultAccountsSettings => {
  const result = createEmptyDefaultAccountsSettings();

  if (!apiData || typeof apiData !== 'object') {
    return result;
  }

  (Object.keys(result) as Array<keyof DefaultAccountsSettings>).forEach((key) => {
    const value = apiData[key];
    if (value !== null && value !== undefined) {
      result[key] = String(value);
    }
  });

  return result;
};

const buildDefaultAccountsPayload = (values: DefaultAccountsSettings): DefaultAccountsSettings => {
  const payload: DefaultAccountsSettings = { ...DEFAULT_ACCOUNTS_PLACEHOLDER };

  (Object.keys(payload) as Array<keyof DefaultAccountsSettings>).forEach((key) => {
    const value = values[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      payload[key] = String(value);
    }
  });

  return payload;
};

