const SETTINGS_SCOPE_BASE_PATH: Record<'accounting' | 'supplier', string> = {
  accounting: '/api/settings',
  supplier: '/api/settings/supplier'
};

const getScopedSettingsPath = (scope: 'accounting' | 'supplier', resource: string, query?: string) => {
  const base = `${SETTINGS_SCOPE_BASE_PATH[scope]}/${resource}`;
  return query ? `${base}?${query}` : base;
};

const mapAutomaticAccountingEntriesFromApi = (entries: any[]): AutomaticAccountingEntry[] =>
  Array.isArray(entries)
    ? entries.map((entry: any) => ({
      id: entry.id,
      number: entry.number,
      name: entry.name,
      account: entry.account,
      any_amount: entry.any_amount,
      basic_accounts: entry.basic_accounts || [],
      formulas: entry.formulas || [],
      transactions: entry.transactions || []
    }))
    : [];

const createTrustedSendersUpdater = (
  setState: React.Dispatch<React.SetStateAction<TrustedSendersData>>
) => {
  const sanitizeList = (list?: string[]) => {
    if (!Array.isArray(list)) return list;
    return Array.from(
      new Set(
        list
          .map(item => item?.trim?.() ?? '')
          .filter((item): item is string => item.length > 0)
      )
    );
  };

  return (updates: Partial<TrustedSendersData>) => {
    setState(prev => {
      const sanitizedUpdates: Partial<TrustedSendersData> = {
        ...updates,
        trustedDomains: sanitizeList(updates.trustedDomains),
        trustedEmailAddresses: sanitizeList(updates.trustedEmailAddresses),
        rejectedEmailAddresses: sanitizeList(updates.rejectedEmailAddresses)
      };

      return {
        ...prev,
        ...sanitizedUpdates,
        trustedDomains: sanitizedUpdates.trustedDomains ?? prev.trustedDomains,
        trustedEmailAddresses: sanitizedUpdates.trustedEmailAddresses ?? prev.trustedEmailAddresses,
        rejectedEmailAddresses: sanitizedUpdates.rejectedEmailAddresses ?? prev.rejectedEmailAddresses
      };
    });
  };
};

