const SupplierPriceListUnitsInterface: React.FC<{ scope?: 'supplier' | 'billing' }> = ({ scope = 'supplier' }) => {
  const [settings, setSettings] = useState<SupplierPriceListUnitsSettings>(
    cloneDefaultPriceListUnits()
  );
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [editingPriceList, setEditingPriceList] = useState<{ id: string; field: string } | null>(null);
  const [editingUnit, setEditingUnit] = useState<{ id: string; field: string } | null>(null);

  const isBusy = isLoading || isSaving;

  useEffect(() => {
    let isMounted = true;

    const loadSettings = async () => {
      setIsLoading(true);
      setError(null);
      setSuccessMessage(null);

      try {
        let data: SupplierPriceListUnitsSettings | null = null;

        if (scope === 'billing') {
          const { billingSettingsService } = await import('../services/billingSettingsService');
          const billingData = await billingSettingsService.getPriceListUnits();
          data = {
            priceLists: billingData.priceLists.map(p => ({
              id: p.id,
              code: p.code,
              name: p.name,
              comment: p.comment,
              preselected: p.preselected
            })),
            units: billingData.units.map(u => ({
              id: u.id,
              code: u.code,
              codeEng: u.codeEng,
              text: u.text
            }))
          };
        } else {
          data = await fetchSupplierInvoiceSection<SupplierPriceListUnitsSettings>(
            'price-list-units'
          );
        }

        if (!isMounted) return;

        setSettings(normalizeSupplierPriceListUnits(data));
        setEditingPriceList(null);
        setEditingUnit(null);
      } catch (err) {
        console.error('❌ Failed to load supplier price list and units settings', err);
        if (isMounted) {
          setError(
            err instanceof Error
              ? err.message
              : 'Failed to load supplier price list and units settings'
          );
          setSettings(cloneDefaultPriceListUnits());
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    loadSettings();

    return () => {
      isMounted = false;
    };
  }, [scope]);

  const updatePriceLists = (updater: (priceLists: SupplierPriceList[]) => SupplierPriceList[]) => {
    setSettings((prev) => ({
      ...prev,
      priceLists: updater(prev.priceLists)
    }));
  };

  const updateUnits = (updater: (units: SupplierUnit[]) => SupplierUnit[]) => {
    setSettings((prev) => ({
      ...prev,
      units: updater(prev.units)
    }));
  };

  const ensurePreselected = (lists: SupplierPriceList[]): SupplierPriceList[] => {
    if (lists.length === 0) return lists;
    if (lists.some((list) => list.preselected)) return lists;
    const [first, ...rest] = lists;
    return [{ ...first, preselected: true }, ...rest];
  };

  const handleAddPriceList = () => {
    setSuccessMessage(null);
    setError(null);
    const newPriceList: SupplierPriceList = {
      id: generateTempId(),
      code: '',
      name: '',
      comment: '',
      preselected: settings.priceLists.length === 0
    };
    updatePriceLists((priceLists) => [...priceLists, newPriceList]);
    setEditingPriceList({ id: newPriceList.id, field: 'code' });
  };

  const handleDeletePriceList = (id: string) => {
    setSuccessMessage(null);
    setError(null);
    updatePriceLists((priceLists) => ensurePreselected(priceLists.filter((list) => list.id !== id)));
    if (editingPriceList?.id === id) {
      setEditingPriceList(null);
    }
  };

  const handleUpdatePriceList = (
    id: string,
    field: keyof SupplierPriceList,
    value: string | boolean
  ) => {
    setSuccessMessage(null);
    setError(null);
    updatePriceLists((priceLists) => {
      const updated = priceLists.map((list) => {
        if (list.id !== id) {
          return field === 'preselected' && value
            ? { ...list, preselected: false }
            : list;
        }
        if (field === 'preselected') {
          return { ...list, preselected: Boolean(value) };
        }
        return { ...list, [field]: value };
      });
      return ensurePreselected(updated);
    });
  };

  const handleAddUnit = () => {
    setSuccessMessage(null);
    setError(null);
    const newUnit: SupplierUnit = {
      id: generateTempId(),
      code: '',
      codeEng: '',
      text: ''
    };
    updateUnits((units) => [...units, newUnit]);
    setEditingUnit({ id: newUnit.id, field: 'code' });
  };

  const handleDeleteUnit = (id: string) => {
    setSuccessMessage(null);
    setError(null);
    updateUnits((units) => units.filter((unit) => unit.id !== id));
    if (editingUnit?.id === id) {
      setEditingUnit(null);
    }
  };

  const handleUpdateUnit = (id: string, field: keyof SupplierUnit, value: string) => {
    setSuccessMessage(null);
    setError(null);
    updateUnits((units) =>
      units.map((unit) => (unit.id === id ? { ...unit, [field]: value } : unit))
    );
  };

  const handleSave = async () => {
    setIsSaving(true);
    setError(null);
    setSuccessMessage(null);

    try {
      const payload: SupplierPriceListUnitsSettings = {
        priceLists: settings.priceLists.map((list) => ({
          id: list.id,
          code: list.code,
          name: list.name,
          comment: list.comment,
          preselected: !!list.preselected
        })),
        units: settings.units.map((unit) => ({
          id: unit.id,
          code: unit.code,
          codeEng: unit.codeEng,
          text: unit.text
        }))
      };

      let saved: SupplierPriceListUnitsSettings;

      if (scope === 'billing') {
        const { billingSettingsService } = await import('../services/billingSettingsService');
        await billingSettingsService.savePriceListUnits({
          priceLists: payload.priceLists,
          units: payload.units
        });
        const updated = await billingSettingsService.getPriceListUnits();
        saved = {
          priceLists: updated.priceLists.map(p => ({
            id: p.id,
            code: p.code,
            name: p.name,
            comment: p.comment,
            preselected: p.preselected
          })),
          units: updated.units.map(u => ({
            id: u.id,
            code: u.code,
            codeEng: u.codeEng,
            text: u.text
          }))
        };
      } else {
        saved = await updateSupplierInvoiceSection<SupplierPriceListUnitsSettings>(
          'price-list-units',
          payload
        );
      }

      setSettings(normalizeSupplierPriceListUnits(saved));
      setSuccessMessage('Price list and units settings saved successfully');
      setEditingPriceList(null);
      setEditingUnit(null);
    } catch (err) {
      console.error('❌ Failed to save supplier price list and units settings', err);
      setError(
        err instanceof Error
          ? err.message
          : 'Failed to save supplier price list and units settings'
      );
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center">
        <div className="w-6 h-6 bg-green-600 rounded-full flex items-center justify-center mr-3">
          <span className="text-white text-sm">✓</span>
        </div>
        <h3 className="text-lg font-medium text-gray-900">Price list and units</h3>
      </div>

      {error && <div className="rounded-md bg-red-50 p-3 text-sm text-red-600">{error}</div>}
      {successMessage && !isLoading && (
        <div className="rounded-md bg-green-50 p-3 text-sm text-green-600">{successMessage}</div>
      )}

      {isLoading ? (
        <div className="text-sm text-gray-500">Loading price lists and units...</div>
      ) : (
        <>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-4">
              <h4 className="text-md font-medium text-gray-800">Price lists</h4>
              <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
                <table className="w-full">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        CODE
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        NAME
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        COMMENT
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        PRESELECTED
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {settings.priceLists.map((list) => (
                      <tr key={list.id} className="hover:bg-gray-50">
                        <td className="px-4 py-3">
                          {editingPriceList?.id === list.id && editingPriceList?.field === 'code' ? (
                            <input
                              type="text"
                              value={list.code}
                              onChange={(e) =>
                                handleUpdatePriceList(list.id, 'code', e.target.value)
                              }
                              onBlur={() => setEditingPriceList(null)}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') setEditingPriceList(null);
                              }}
                              className="w-full px-2 py-1 border border-gray-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-green-500"
                              autoFocus
                              disabled={isBusy}
                            />
                          ) : (
                            <div
                              onClick={() => !isBusy && setEditingPriceList({ id: list.id, field: 'code' })}
                              className={`px-2 py-1 rounded text-sm ${isBusy ? 'text-gray-400 cursor-not-allowed' : 'cursor-pointer hover:bg-gray-100'
                                }`}
                            >
                              {list.code || 'Click to edit'}
                            </div>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          {editingPriceList?.id === list.id && editingPriceList?.field === 'name' ? (
                            <input
                              type="text"
                              value={list.name}
                              onChange={(e) =>
                                handleUpdatePriceList(list.id, 'name', e.target.value)
                              }
                              onBlur={() => setEditingPriceList(null)}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') setEditingPriceList(null);
                              }}
                              className="w-full px-2 py-1 border border-gray-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-green-500"
                              autoFocus
                              disabled={isBusy}
                            />
                          ) : (
                            <div
                              onClick={() => !isBusy && setEditingPriceList({ id: list.id, field: 'name' })}
                              className={`px-2 py-1 rounded text-sm ${isBusy ? 'text-gray-400 cursor-not-allowed' : 'cursor-pointer hover:bg-gray-100'
                                }`}
                            >
                              {list.name || 'Click to edit'}
                            </div>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          {editingPriceList?.id === list.id && editingPriceList?.field === 'comment' ? (
                            <input
                              type="text"
                              value={list.comment}
                              onChange={(e) =>
                                handleUpdatePriceList(list.id, 'comment', e.target.value)
                              }
                              onBlur={() => setEditingPriceList(null)}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') setEditingPriceList(null);
                              }}
                              className="w-full px-2 py-1 border border-gray-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-green-500"
                              autoFocus
                              disabled={isBusy}
                            />
                          ) : (
                            <div
                              onClick={() => !isBusy && setEditingPriceList({ id: list.id, field: 'comment' })}
                              className={`px-2 py-1 rounded text-sm ${isBusy ? 'text-gray-400 cursor-not-allowed' : 'cursor-pointer hover:bg-gray-100'
                                }`}
                            >
                              {list.comment || 'Click to edit'}
                            </div>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          <input
                            type="radio"
                            name="supplier-price-list-preselected"
                            checked={list.preselected}
                            disabled={isBusy}
                            onChange={(e) =>
                              handleUpdatePriceList(list.id, 'preselected', e.target.checked)
                            }
                            className="h-4 w-4 text-green-600 focus:ring-green-500 border-gray-300"
                          />
                        </td>
                        <td className="px-4 py-3">
                          <button
                            onClick={() => handleDeletePriceList(list.id)}
                            disabled={isBusy}
                            className={`text-red-600 ${isBusy ? 'opacity-60 cursor-not-allowed' : 'hover:text-red-800'
                              }`}
                          >
                            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                              <path
                                fillRule="evenodd"
                                d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z"
                                clipRule="evenodd"
                              />
                            </svg>
                          </button>
                        </td>
                      </tr>
                    ))}
                    <tr>
                      <td colSpan={5} className="px-4 py-3">
                        <button
                          onClick={handleAddPriceList}
                          disabled={isBusy}
                          className={`w-full text-left px-2 py-1 rounded text-sm ${isBusy
                            ? 'text-gray-400 cursor-not-allowed'
                            : 'text-gray-500 hover:text-gray-700 hover:bg-gray-50'
                            }`}
                        >
                          + Add new price list
                        </button>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
            <div className="space-y-4">
              <h4 className="text-md font-medium text-gray-800">Units</h4>
              <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
                <table className="w-full">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        CODE
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        CODE ENG
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        TEXT
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {settings.units.map((unit) => (
                      <tr key={unit.id} className="hover:bg-gray-50">
                        <td className="px-4 py-3">
                          {editingUnit?.id === unit.id && editingUnit?.field === 'code' ? (
                            <input
                              type="text"
                              value={unit.code}
                              onChange={(e) => handleUpdateUnit(unit.id, 'code', e.target.value)}
                              onBlur={() => setEditingUnit(null)}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') setEditingUnit(null);
                              }}
                              className="w-full px-2 py-1 border border-gray-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-green-500"
                              autoFocus
                              disabled={isBusy}
                            />
                          ) : (
                            <div
                              onClick={() => !isBusy && setEditingUnit({ id: unit.id, field: 'code' })}
                              className={`px-2 py-1 rounded text-sm ${isBusy ? 'text-gray-400 cursor-not-allowed' : 'cursor-pointer hover:bg-gray-100'
                                }`}
                            >
                              {unit.code || 'Click to edit'}
                            </div>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          {editingUnit?.id === unit.id && editingUnit?.field === 'codeEng' ? (
                            <input
                              type="text"
                              value={unit.codeEng}
                              onChange={(e) => handleUpdateUnit(unit.id, 'codeEng', e.target.value)}
                              onBlur={() => setEditingUnit(null)}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') setEditingUnit(null);
                              }}
                              className="w-full px-2 py-1 border border-gray-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-green-500"
                              autoFocus
                              disabled={isBusy}
                            />
                          ) : (
                            <div
                              onClick={() => !isBusy && setEditingUnit({ id: unit.id, field: 'codeEng' })}
                              className={`px-2 py-1 rounded text-sm ${isBusy ? 'text-gray-400 cursor-not-allowed' : 'cursor-pointer hover:bg-gray-100'
                                }`}
                            >
                              {unit.codeEng || 'Click to edit'}
                            </div>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          {editingUnit?.id === unit.id && editingUnit?.field === 'text' ? (
                            <input
                              type="text"
                              value={unit.text}
                              onChange={(e) => handleUpdateUnit(unit.id, 'text', e.target.value)}
                              onBlur={() => setEditingUnit(null)}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') setEditingUnit(null);
                              }}
                              className="w-full px-2 py-1 border border-gray-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-green-500"
                              autoFocus
                              disabled={isBusy}
                            />
                          ) : (
                            <div
                              onClick={() => !isBusy && setEditingUnit({ id: unit.id, field: 'text' })}
                              className={`px-2 py-1 rounded text-sm ${isBusy ? 'text-gray-400 cursor-not-allowed' : 'cursor-pointer hover:bg-gray-100'
                                }`}
                            >
                              {unit.text || 'Click to edit'}
                            </div>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          <button
                            onClick={() => handleDeleteUnit(unit.id)}
                            disabled={isBusy}
                            className={`text-red-600 ${isBusy ? 'opacity-60 cursor-not-allowed' : 'hover:text-red-800'
                              }`}
                          >
                            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                              <path
                                fillRule="evenodd"
                                d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z"
                                clipRule="evenodd"
                              />
                            </svg>
                          </button>
                        </td>
                      </tr>
                    ))}
                    <tr>
                      <td colSpan={4} className="px-4 py-3">
                        <button
                          onClick={handleAddUnit}
                          disabled={isBusy}
                          className={`w-full text-left px-2 py-1 rounded text-sm ${isBusy
                            ? 'text-gray-400 cursor-not-allowed'
                            : 'text-gray-500 hover:text-gray-700 hover:bg-gray-50'
                            }`}
                        >
                          + Add new unit
                        </button>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </div>

          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 flex items-start space-x-3">
            <div className="w-6 h-6 bg-green-600 rounded-full flex items-center justify-center flex-shrink-0">
              <span className="text-white text-sm">i</span>
            </div>
            <div className="text-sm text-gray-700">
              Price lists and units saved here become available across your accounting workflows. Review
              the entries carefully before saving.
            </div>
          </div>
        </>
      )}

      {error && <div className="rounded-md bg-red-50 p-3 text-sm text-red-600">{error}</div>}
      {successMessage && (
        <div className="rounded-md bg-green-50 p-3 text-sm text-green-600">{successMessage}</div>
      )}

      {isLoading ? (
        <div className="text-sm text-gray-500">Loading price list and units...</div>
      ) : null}

      <div className="flex justify-end">
        <button
          onClick={handleSave}
          disabled={isBusy}
          className={`bg-green-600 text-white px-6 py-2 rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 ${isBusy ? 'opacity-60 cursor-not-allowed' : 'hover:bg-green-700'
            }`}
        >
          {isSaving ? 'Saving...' : 'Save'}
        </button>
      </div>
    </div>
  );
};

// Quote/Order Project Interface Component
const QuoteOrderProjectInterface: React.FC = () => {
  const [settings, setSettings] = useState({
    enableSupportForProjectAccounting: true,
    includeProjectsOnTabEnterInput: false
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;

    const loadSettings = async () => {
      setIsLoading(true);
      setError(null);

      try {
        const data = await fetchQuoteOrderInvoiceSection<{
          enableSupportForProjectAccounting?: boolean;
          includeProjectsOnTabEnterInput?: boolean;
        }>('project');

        if (!isMounted) return;

        if (data.enableSupportForProjectAccounting !== undefined) {
          setSettings(prev => ({ ...prev, enableSupportForProjectAccounting: data.enableSupportForProjectAccounting! }));
        }
        if (data.includeProjectsOnTabEnterInput !== undefined) {
          setSettings(prev => ({ ...prev, includeProjectsOnTabEnterInput: data.includeProjectsOnTabEnterInput! }));
        }
      } catch (err) {
        console.error('❌ Failed to load quote/order project settings', err);
        if (isMounted) {
          setError(err instanceof Error ? err.message : 'Failed to load settings');
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    loadSettings();

    return () => {
      isMounted = false;
    };
  }, []);

  const handleToggle = (key: keyof typeof settings) => {
    setSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleSave = async () => {
    setIsSaving(true);
    setError(null);
    setSuccessMessage(null);

    try {
      await updateQuoteOrderInvoiceSection('project', settings);
      setSuccessMessage('Project settings saved successfully');
    } catch (err) {
      console.error('❌ Failed to save quote/order project settings', err);
      setError(err instanceof Error ? err.message : 'Failed to save settings');
    } finally {
      setIsSaving(false);
    }
  };

  const ToggleSwitch = ({
    value,
    onChange,
    options = ['Yes', 'No']
  }: {
    value: boolean;
    onChange: () => void;
    options?: [string, string];
  }) => (
    <div className="flex space-x-1">
      <button
        onClick={onChange}
        className={`px-4 py-2 rounded-l-lg border transition-colors ${value
          ? 'bg-green-600 text-white border-green-600'
          : 'bg-white text-gray-900 border-gray-300 hover:bg-gray-50'
          }`}
      >
        {options[0]}
      </button>
      <button
        onClick={onChange}
        className={`px-4 py-2 rounded-r-lg border transition-colors ${!value
          ? 'bg-gray-200 text-gray-700 border-gray-200'
          : 'bg-white text-gray-900 border-gray-300 hover:bg-gray-50'
          }`}
      >
        {options[1]}
      </button>
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex items-center">
        <div className="w-6 h-6 bg-green-600 rounded-full flex items-center justify-center mr-3">
          <span className="text-white text-sm">✓</span>
        </div>
        <h3 className="text-lg font-medium text-gray-900">Project</h3>
      </div>

      {error && <div className="rounded-md bg-red-50 p-3 text-sm text-red-600">{error}</div>}
      {successMessage && (
        <div className="rounded-md bg-green-50 p-3 text-sm text-green-600">{successMessage}</div>
      )}

      {isLoading ? (
        <div className="text-sm text-gray-500">Loading project settings...</div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Enable support for project accounting
              </label>
              <ToggleSwitch
                value={settings.enableSupportForProjectAccounting}
                onChange={() => handleToggle('enableSupportForProjectAccounting')}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Include projects on tab/enter input
              </label>
              <ToggleSwitch
                value={settings.includeProjectsOnTabEnterInput}
                onChange={() => handleToggle('includeProjectsOnTabEnterInput')}
              />
            </div>
          </div>
          <div>
            <p className="text-sm text-gray-700">
              To add a new project, go to:{' '}
              <a
                href="#"
                className="text-blue-600 hover:text-blue-800 underline"
              >
                Register - Projects
              </a>
            </p>
          </div>
        </>
      )}

      <div className="flex justify-end">
        <button
          onClick={handleSave}
          disabled={isSaving || isLoading}
          className={`bg-green-600 text-white px-6 py-2 rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 ${isSaving || isLoading ? 'opacity-60 cursor-not-allowed' : 'hover:bg-green-700'
            }`}
        >
          {isSaving ? 'Saving...' : 'Save'}
        </button>
      </div>
    </div>
  );
};

// Quote/Order Reports Interface Component
const QuoteOrderReportsInterface: React.FC = () => {
  const [settings, setSettings] = useState({
    leaveReportSelectionWindowOpenAfterPrinting: false
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;

    const loadSettings = async () => {
      setIsLoading(true);
      setError(null);

      try {
        const data = await fetchQuoteOrderInvoiceSection<{
          leaveReportSelectionWindowOpenAfterPrinting?: boolean;
        }>('reports');

        if (!isMounted) return;

        if (data.leaveReportSelectionWindowOpenAfterPrinting !== undefined) {
          setSettings({ leaveReportSelectionWindowOpenAfterPrinting: data.leaveReportSelectionWindowOpenAfterPrinting });
        }
      } catch (err) {
        console.error('❌ Failed to load quote/order reports settings', err);
        if (isMounted) {
          setError(err instanceof Error ? err.message : 'Failed to load settings');
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    loadSettings();

    return () => {
      isMounted = false;
    };
  }, []);

  const handleToggle = () => {
    setSettings(prev => ({ ...prev, leaveReportSelectionWindowOpenAfterPrinting: !prev.leaveReportSelectionWindowOpenAfterPrinting }));
  };

  const handleSave = async () => {
    setIsSaving(true);
    setError(null);
    setSuccessMessage(null);

    try {
      await updateQuoteOrderInvoiceSection('reports', settings);
      setSuccessMessage('Reports settings saved successfully');
    } catch (err) {
      console.error('❌ Failed to save quote/order reports settings', err);
      setError(err instanceof Error ? err.message : 'Failed to save settings');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center">
        <div className="w-6 h-6 bg-green-600 rounded-full flex items-center justify-center mr-3">
          <span className="text-white text-sm">✓</span>
        </div>
        <h3 className="text-lg font-medium text-gray-900">Reports</h3>
      </div>

      {error && <div className="rounded-md bg-red-50 p-3 text-sm text-red-600">{error}</div>}
      {successMessage && (
        <div className="rounded-md bg-green-50 p-3 text-sm text-green-600">{successMessage}</div>
      )}

      {isLoading ? (
        <div className="text-sm text-gray-500">Loading reports settings...</div>
      ) : (
        <div className="flex items-center justify-between">
          <label className="text-sm font-medium text-gray-700">
            Leave report selection window open after printing
          </label>
          <button
            onClick={handleToggle}
            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 ${settings.leaveReportSelectionWindowOpenAfterPrinting ? 'bg-green-600' : 'bg-gray-200'
              }`}
          >
            <span
              className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${settings.leaveReportSelectionWindowOpenAfterPrinting ? 'translate-x-6' : 'translate-x-1'
                }`}
            />
          </button>
        </div>
      )}

      <div className="flex justify-end">
        <button
          onClick={handleSave}
          disabled={isSaving || isLoading}
          className={`bg-green-600 text-white px-6 py-2 rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 ${isSaving || isLoading ? 'opacity-60 cursor-not-allowed' : 'hover:bg-green-700'
            }`}
        >
          {isSaving ? 'Saving...' : 'Save'}
        </button>
      </div>
    </div>
  );
};

