  const fetchVerificationSeriesSettings = async (category: VerificationSeriesCategory) => {
    if (category === 'supplier') {
      setSupplierVerificationSeriesLoading(true);
      setSupplierVerificationSeriesError(null);
      setSupplierVerificationSeriesSuccess(null);
    }

    try {
      const cacheBuster = `_t=${Date.now()}`;
      const response = await apiFetch(
        `/api/settings/verification-series?category=${category}&${cacheBuster}`,
        { method: 'GET' }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data?.message || `Failed to fetch ${category} verification series`);
      }

      if (!data?.success || !data?.data) {
        return;
      }

      const categoryData = data.data[category] || {};

      const formattedSeries = Array.isArray(categoryData.series)
        ? categoryData.series.map((item: any) => ({
          id: item.id || generateClientId(),
          code: item.code || '',
          name: item.name || '',
          manualAccounting: !!item.manualAccounting
        }))
        : [];

      if (category === 'accounting') {
        setVerificationSeriesData(formattedSeries);
      } else if (category === 'supplier') {
        setSupplierVerificationSeriesData(formattedSeries);
      } else {
        setBillingVerificationSeriesData(formattedSeries);
      }

      if (categoryData.dropdownSelections && typeof categoryData.dropdownSelections === 'object') {
        setVerificationSeriesSelections(prev => ({
          ...prev,
          [category]: {
            ...prev[category],
            ...categoryData.dropdownSelections
          }
        }));
      }
    } catch (error) {
      console.error(`❌ Error fetching ${category} verification series settings:`, error);
      if (category === 'supplier') {
        setSupplierVerificationSeriesError(
          error instanceof Error ? error.message : 'Failed to fetch verification series'
        );
      } else {
        alert(
          `Failed to fetch ${category} verification series: ${error instanceof Error ? error.message : 'Unknown error'
          }`
        );
      }
    } finally {
      if (category === 'supplier') {
        setSupplierVerificationSeriesLoading(false);
      }
    }
  };

  const saveVerificationSeriesSettings = async (category: VerificationSeriesCategory) => {
    if (category === 'supplier') {
      setSupplierVerificationSeriesSaving(true);
      setSupplierVerificationSeriesError(null);
      setSupplierVerificationSeriesSuccess(null);
    }

    const seriesState =
      category === 'accounting'
        ? verificationSeriesData
        : category === 'supplier'
          ? supplierVerificationSeriesData
          : billingVerificationSeriesData;

    const payload = {
      category,
      series: seriesState.map((item, index) => ({
        id: item.id,
        code: item.code,
        name: item.name,
        manualAccounting: item.manualAccounting,
        position: index
      })),
      dropdownSelections: verificationSeriesSelections[category]
    };

    try {
      const response = await apiFetch('/api/settings/verification-series', {
        method: 'PUT',
        json: payload
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data?.message || `Failed to save ${category} verification series`);
      }

      if (data?.success && data?.data) {
        const formattedSeries = Array.isArray(data.data.series)
          ? data.data.series.map((item: any) => ({
            id: item.id || generateClientId(),
            code: item.code || '',
            name: item.name || '',
            manualAccounting: !!item.manualAccounting
          }))
          : [];

        if (category === 'accounting') {
          setVerificationSeriesData(formattedSeries);
        } else if (category === 'supplier') {
          setSupplierVerificationSeriesData(formattedSeries);
        } else {
          setBillingVerificationSeriesData(formattedSeries);
        }

        if (data.data.dropdownSelections && typeof data.data.dropdownSelections === 'object') {
          setVerificationSeriesSelections(prev => ({
            ...prev,
            [category]: {
              ...prev[category],
              ...data.data.dropdownSelections
            }
          }));
        }
      }

      if (category === 'supplier') {
        await fetchVerificationSeriesSettings('supplier');
        setSupplierVerificationSeriesSuccess('Verification series saved successfully');
      } else {
        alert('Settings saved successfully!');
      }
    } catch (error) {
      console.error(`❌ Error saving ${category} verification series settings:`, error);
      if (category === 'supplier') {
        setSupplierVerificationSeriesError(
          error instanceof Error ? error.message : 'Failed to save verification series'
        );
      } else {
        alert(
          `Failed to save verification series: ${error instanceof Error ? error.message : 'Unknown error'
          }`
        );
      }
    } finally {
      if (category === 'supplier') {
        setSupplierVerificationSeriesSaving(false);
      }
    }
  };

