  const toggleSection = (sectionId: string) => {
    setExpandedSections(prev => {
      // If the section is currently expanded, collapse it
      if (prev[sectionId]) {
        return {
          ...prev,
          [sectionId]: false
        };
      } else {
        // If the section is collapsed, expand it and collapse all others
        const newState: Record<string, boolean> = {};
        Object.keys(prev).forEach(key => {
          newState[key] = key === sectionId;
        });
        return newState;
      }
    });
  };

  const handleCheckboxChange = (sectionId: string, itemId: string) => {
    // Handle checkbox toggle logic for verification series
    if (sectionId === 'verification-series') {
      setVerificationSeriesData(prev =>
        prev.map(item =>
          item.id === itemId
            ? { ...item, manualAccounting: !item.manualAccounting }
            : item
        )
      );
    } else if (sectionId === 'supplier-verification-series') {
      setSupplierVerificationSeriesSuccess(null);
      setSupplierVerificationSeriesError(null);
      setSupplierVerificationSeriesData(prev =>
        prev.map(item =>
          item.id === itemId
            ? { ...item, manualAccounting: !item.manualAccounting }
            : item
        )
      );
    }
  };

  const handleDropdownChange = (sectionId: string, dropdownId: string, value: string) => {
    const sectionToCategoryMap: Record<string, VerificationSeriesCategory | undefined> = {
      'verification-series': 'accounting',
      'supplier-verification-series': 'supplier',
      'billing-verification-series': 'billing'
    };

    const category = sectionToCategoryMap[sectionId];

    if (!category) {
      console.warn('Unknown verification series section:', sectionId);
      return;
    }

    if (category === 'supplier' && supplierVerificationSeriesDisabled) {
      return;
    }

    if (category === 'supplier') {
      setSupplierVerificationSeriesSuccess(null);
      setSupplierVerificationSeriesError(null);
    }

    setVerificationSeriesSelections(prev => ({
      ...prev,
      [category]: {
        ...prev[category],
        [dropdownId]: value
      }
    }));

    if (category === 'supplier') {
      setSupplierVerificationSeriesSuccess(null);
      setSupplierVerificationSeriesError(null);
    }

    console.log('Change dropdown:', sectionId, dropdownId, value);
  };

