  // Save facility register settings to API
  const handleFacilityRegisterSave = async () => {
    setFacilityRegisterSaving(true);
    try {
      const response = await apiFetch('/api/settings/facility-register', {
        method: 'POST',
        json: {
          proposedDepreciationStartDate: facilityRegisterSettings.proposedDepreciationStartDate,
          createAssetFromSupplierInvoice: facilityRegisterSettings.createAssetFromSupplierInvoice,
          enableComponentDepreciationSupport: facilityRegisterSettings.enableComponentDepreciationSupport
        }
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to save facility register settings');
      }

      const data = await response.json();
      if (data.success) {
        // Show success message (you can add a toast notification here)
        alert('Facility register settings saved successfully!');
      }
    } catch (error) {
      console.error('Error saving facility register settings:', error);
      alert(`Failed to save settings: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setFacilityRegisterSaving(false);
    }
  };

