  const handleBillingVATSaveEntry = (entryData: Partial<VATEntry>) => {
    if (billingVatData.isCreating) {
      const newEntry: VATEntry = {
        id: Date.now().toString(),
        vatCode: entryData.vatCode || '',
        description: entryData.description || '',
        vatRate: entryData.vatRate || '',
        validFrom: entryData.validFrom || '',
        validTo: entryData.validTo || '',
        isDeletable: entryData.isDeletable || true
      };
      setBillingVatData(prev => ({
        ...prev,
        settings: {
          ...prev.settings,
          outputVATEntries: [...prev.settings.outputVATEntries, newEntry]
        },
        currentView: 'list',
        isCreating: false,
        editingEntry: null
      }));
    } else if (billingVatData.editingEntry) {
      setBillingVatData(prev => ({
        ...prev,
        settings: {
          ...prev.settings,
          outputVATEntries: prev.settings.outputVATEntries.map(entry =>
            entry.id === billingVatData.editingEntry!.id
              ? { ...entry, ...entryData }
              : entry
          )
        },
        currentView: 'list',
        isCreating: false,
        editingEntry: null
      }));
    }
  };

