    // Update local state immediately for UI responsiveness
    setLockingPeriodData(prev => {
      const updatedManualLocking = prev.manualPeriodLocking.map(user =>
        user.id === userId ? { ...user, [field]: value } : user
      );

      // Save to backend
      apiFetch('/api/settings/locking-period', {
        method: 'PUT',
        json: {
          automaticPeriodLocking: prev.automaticPeriodLocking,
          manualPeriodLocking: updatedManualLocking
        }
      }).then(async (response) => {
        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.message || 'Failed to update locking period settings');
        }
        // Refresh data after save
        await fetchLockingPeriod();
      }).catch((error) => {
        console.error('❌ Error updating locking period user:', error);
        // Revert on error
        fetchLockingPeriod();
      });

      return {
        ...prev,
        manualPeriodLocking: updatedManualLocking
      };
    });
