  const handleVATSaveEntry = async (entryData: Partial<VATEntry>) => {
    try {
      if (vatData.isCreating) {
        // Create new entry
        const response = await apiFetch('/api/settings/vat/entries', {
          method: 'POST',
          json: {
            vat_code: entryData.vatCode || '',
            description: entryData.description || '',
            vat_rate: entryData.vatRate || '',
            valid_from: entryData.validFrom || null,
            valid_to: entryData.validTo || null
          }
        });

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.message || 'Failed to create VAT entry');
        }

        const data = await response.json();
        if (data.success) {
          // Refresh VAT settings to get updated entries
          await fetchVATSettings();
          handleVATShowList();
          alert('VAT entry created successfully!');
        }
      } else if (vatData.editingEntry) {
        // Update existing entry
        const entryId = vatData.editingEntry.id;
        const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(entryId);

        if (isUUID) {
          const response = await apiFetch(`/api/settings/vat/entries/${entryId}`, {
            method: 'PUT',
            json: {
              vat_code: entryData.vatCode,
              description: entryData.description,
              vat_rate: entryData.vatRate,
              valid_from: entryData.validFrom || null,
              valid_to: entryData.validTo || null
            }
          });

          if (!response.ok) {
            const errorData = await response.json();
            throw new Error(errorData.message || 'Failed to update VAT entry');
          }

          // Refresh VAT settings to get updated entries
          await fetchVATSettings();
          handleVATShowList();
          alert('VAT entry updated successfully!');
        } else {
          // Temporary ID - just update local state
          const updatedEntry: VATEntry = {
            ...vatData.editingEntry,
            ...entryData
          };
          setVatData(prev => ({
            ...prev,
            settings: {
              ...prev.settings,
              outputVATEntries: prev.settings.outputVATEntries.map(entry =>
                entry.id === updatedEntry.id ? updatedEntry : entry
              )
            },
            currentView: 'list'
          }));
        }
      }
    } catch (error) {
      console.error('❌ Error saving VAT entry:', error);
      alert(`Failed to save: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  };

