  // Load Quote/Order VAT settings
  useEffect(() => {
    let isMounted = true;

    const loadQuoteOrderVATSettings = async () => {
      setQuoteOrderVatLoading(true);
      setQuoteOrderVatError(null);

      try {
        const data = await fetchQuoteOrderInvoiceSection<{
          vatType?: string;
          about?: string;
          proposeVatOnSupplierInvoices?: string;
          incomingInvoicesAction?: 'proposed' | 'interpret' | 'ignore';
          outputVATEntries?: VATEntry[];
        }>('vat');

        if (!isMounted) return;

        setQuoteOrderVatData(prev => ({
          ...prev,
          settings: {
            vatType: data.vatType !== undefined ? data.vatType : (prev.settings.vatType || 'Annual VAT'),
            about: data.about !== undefined ? data.about : (prev.settings.about || ''),
            proposeVatOnSupplierInvoices: data.proposeVatOnSupplierInvoices !== undefined ? data.proposeVatOnSupplierInvoices : (prev.settings.proposeVatOnSupplierInvoices || 'Always'),
            incomingInvoicesAction: data.incomingInvoicesAction || prev.settings.incomingInvoicesAction || 'proposed',
            outputVATEntries: data.outputVATEntries !== undefined ? data.outputVATEntries : (prev.settings.outputVATEntries || [])
          }
        }));
      } catch (err) {
        console.error('❌ Failed to load quote/order VAT settings', err);
        if (isMounted) {
          setQuoteOrderVatError(err instanceof Error ? err.message : 'Failed to load settings');
        }
      } finally {
        if (isMounted) {
          setQuoteOrderVatLoading(false);
        }
      }
    };

    loadQuoteOrderVATSettings();

    return () => {
      isMounted = false;
    };
  }, []);

